                            if not math.isfinite(product):
                                raise ValueError(
                                    "conv_transpose2d_multi "
                                    "intermediate must be finite"
                                )
                            out_data[z] = out_data[z] + product
                            if not math.isfinite(out_data[z]):
                                raise ValueError(
                                    "conv_transpose2d_multi "
                                    "intermediate must be finite"
                                )
    if not (self.requires_grad or kernel.requires_grad):
        return Tensor._make(
            out_data, False, (), None,
            grad_validator=lambda g: _validate_vector_grad(g, total_out),
        )
    parent_self, parent_kernel = self, kernel

    def backward_fn(grad):
        # dx[i] += g[z]*w[j] and dw[j] += g[z]*x[i], accumulated from
        # 0.0 in the same ascending (c, r, q, o, kr, kc) order and
        # i/j/z indexing as the forward pass. A non-finite product or
        # partial sum aborts the whole pass before any grad is written.
        dx = [0.0] * (C * N * N)
        dw = [0.0] * (C * O * K * K)
