            for r in range(N):
                for q in range(N):
                    i = (c * N + r) * N + q
                    for o in range(O):
                        for kr in range(K):
                            for kc in range(K):
                                j = ((c * O + o) * K + kr) * K + kc
                                z = (o * L + r + kr) * L + q + kc
