    out_data = [0.0] * out_len
    for b in range(B):
        for o in range(O):
            g = o // FPG
            c0 = g * CPG
            bias_o = snapshot_b[o] if snapshot_b is not None else 0.0
            for orow in range(out_h):
                for ocol in range(out_w):
                    oi = ((b * O + o) * out_h + orow) * out_w + ocol
                    acc = bias_o
                    for cl in range(CPG):
                        c = c0 + cl
                        for kr in range(K):
                            r = orow * S + kr * D - P
                            if not 0 <= r < H:
                                continue
                            for kc in range(K):
                                q = ocol * S + kc * D - P
