                                    ((b * C + c) * H + r) * W + q
                                )
                                wi = ((o * CPG + cl) * K + kr) * K + kc
                                product = snapshot_x[xi] * snapshot_w[wi]
                                if not math.isfinite(product):
                                    raise ValueError(
                                        "conv2d_batch intermediate must"
                                        " be finite"
                                    )
                                acc = acc + product
                                if not math.isfinite(acc):
                                    raise ValueError(
                                        "conv2d_batch intermediate must"
                                        " be finite"
                                    )
